test-case.name:
Test help for New-EntraCustomToken.should not be auto-generated(@{details=@{name=New-EntraCustomToken; description=System.Management.Automation.PSObject[]}; examples=@{example=@{code=New-EntraCustomToken -Service AzDevMyProject -ServiceUrl 'https://dev.azure.com/contoso/myproject/_apis/wit' -Data @{ PAT = $pat } -HeaderCode {
	param ($Token)
	$base64AuthInfo = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes(':' + $($Token.Data.PAT | ConvertFrom-SecureString -AsPlainText)))
       return @{
           Authorization  = "Basic $base64AuthInfo"
           'Content-Type' = 'application/json'
       }
}; introduction=System.Management.Automation.PSObject[]; remarks=System.Management.Automation.PSObject[]; title=-------------------------- EXAMPLE 1 --------------------------}}; description=System.Management.Automation.PSObject[]; syntax=@{syntaxItem=@{name=New-EntraCustomToken; parameter=System.Management.Automation.PSObject[]}}; parameters=@{parameter=System.Management.Automation.PSObject[]}; xmlns:maml=http://schemas.microsoft.com/maml/2004/10; xmlns:command=http://schemas.microsoft.com/maml/dev/command/2004/10; xmlns:dev=http://schemas.microsoft.com/maml/dev/2004/10; Name=New-EntraCustomToken; Category=Function; Synopsis=Create a custom token compatible with EntraAuth.; Component=; Role=; Functionality=; ModuleName=PSMicrosoftEntraID})

